style.css:
@-moz-document domain("roblox.com") {
html, body, #__next {
        background: transparent !important;
    }

    body::before {
        content: "";
        position: fixed;
        top: 0;
        left: 0;
        width: 100vw;
        height: 100vh;
        background-image: url("https://userstyles.org/style_sheets/ba194e20d557c6207912f2106921ca33.gif");
        background-size: cover;
        background-position: center;
        background-repeat: no-repeat;
        z-index: -1;
    }

    /* ALLE Hauptcontainer transparent machen */
    div[class*="container"],
    div[class*="content"],
    div[class*="page"],
    div[class*="section"] {
        background: transparent !important;
    }

    /* Topbar */
    header, nav {
        background-color: rgba(0, 0, 0, 0.6) !important;
        backdrop-filter: blur(6px);
    }

    /* Sidebar */
    aside {
        background-color: rgba(0, 0, 0, 0.5) !important;
        backdrop-filter: blur(6px);
    }

    /* Karten / Spiele */
    div[class*="card"],
    div[class*="game"] {
        background-color: rgba(0, 0, 0, 0.4) !important;
        border-radius: 12px !important;
    }

    /* Text */
    * {
        color: #ff7ac3 !important;
    }
}
